// Writes src/generated/build-info.ts: the site's version, the commit, and the branch it was built from.
// Run automatically before the build, the tests, the type check and the dev server (see package.json).
//
// Why a generated file: Netlify gives COMMIT_REF and BRANCH to the build, but not to a function while it runs, so a
// function cannot ask for them when it signs a transcript. The build writes them into the code instead.
// The file is not committed (see .gitignore); it is rebuilt every time.
import { execFileSync } from 'node:child_process';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { join } from 'node:path';

const root = fileURLToPath(new URL('..', import.meta.url));
const git = (args) => {
  try {
    return execFileSync('git', args, { cwd: root, stdio: ['ignore', 'pipe', 'ignore'] }).toString().trim();
  } catch {
    return '';
  }
};

const version = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8')).version;
const commit = (process.env.COMMIT_REF || git(['rev-parse', 'HEAD'])).toLowerCase().replace(/[^0-9a-f]/g, '').slice(0, 40);
const branch = process.env.BRANCH || git(['rev-parse', '--abbrev-ref', 'HEAD']) || '';
const info = { version, commit, branch };

mkdirSync(join(root, 'src', 'generated'), { recursive: true });
writeFileSync(
  join(root, 'src', 'generated', 'build-info.ts'),
  `// Generated by scripts/write-build-info.mjs. Do not edit; not committed.\nexport const BUILD_INFO = ${JSON.stringify(info)};\n`
);
